import {SHOOTHOUSE_RAMPS} from './shoothouse-art.js';
// Preserve the sky from the approved color study; world paint has its own ramp.
export const SHOOTHOUSE_SKY=['#102037','#263b59','#4a6682','#7899b0','#aecbd9','#e3ece8','#12316e','#1954ad','#347fd5','#72b4ef','#badfff','#073f55','#086f86','#12a5b4','#58ced1','#b7e8df','#62263d','#a73547','#df5145','#fa8859','#ffc58e','#332747','#583b79','#8861b0','#bb93d3','#e5d0ee','#60422e','#a36b2d','#dba137','#efc76c','#f6dfa6','#fff0d2'];
function lookup(name,colors){return `vec3 ${name}(vec3 c){vec3 best=vec3(0.);float dst=100.;for(int i=0;i<${colors.length};i++){vec3 p=vec3(0.);${colors.map((hex,i)=>'if(i=='+i+')p=vec3('+hex.match(/\w\w/g).map(v=>(parseInt(v,16)/255).toFixed(5)).join(',')+');').join('')}vec3 cc=c-vec3(min(c.r,min(c.g,c.b))),pc=p-vec3(min(p.r,min(p.g,p.b)));float chroma=max(c.r,max(c.g,c.b))-min(c.r,min(c.g,c.b));float hue=length(normalize(cc+vec3(.00001))-normalize(pc+vec3(.00001)));float d=dot((c-p)*vec3(.9,1.1,.8),c-p)+hue*.22*smoothstep(.035,.12,chroma);if(d<dst){dst=d;best=p;}}return best;}`;}
export const shootHousePaletteGLSL='uniform float arenaArt;\n'+lookup('shootHousePalette',SHOOTHOUSE_RAMPS)+'\n'+lookup('shootHouseSky',SHOOTHOUSE_SKY);
